```

### 【TT OJ】[P1001. 逆序对](https://oj.tt-chen.cc.cd/problems/42)

分析：

可以把这个问题转化为：

从左到右扫描，对于每个数，看它的左侧有多少比它大的数，加入答案。

处理“左侧有多少比它大的数”时可以用到**权值树状数组**。

简单来说，就是把数作为数组的下标。当你想加入 $x$ 时，只需要在下标为 $x$ 处加一；当你想统计当前比 $x$ 大的数的个数时，只需要累加下标为 $x+1 \sim n$ 的数即可（即后缀查询）；实现时，用当前已插入的元素个数减去前缀查询结果。

```cpp
#include<bits/stdc++.h>
#define for_i(i,l,r) for(int i=(l);i<=(r);i++)
#define for_j(i,r,l) for(int i=(r);i>=(l);i--)
#define ll long long
#define endl '\n'
using namespace std;
const int N=1e5+10;
int a[N],n;
ll c[N],ans;
ll query(int x)
{
    ll s=0;
    while(x)
    {
        s+=c[x];
        x-=x&(-x);
    }
    return s;
}
void modify(int x)
{
    while(x<=n)
    {
        c[x]++;
        x+=x&(-x);
    }
}
int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
//	freopen(".in","r",stdin);
//	freopen(".out","w",stdout);
    cin>>n;
    for_i(i,1,n) cin>>a[i];
    for_i(i,1,n)
    {
        ans+=i-1-query(a[i]);
        modify(a[i]);
    }
    cout<<ans;
    return 0;
}
```

### 【洛谷】[P3368 【模板】树状数组 2](https://www.luogu.com.cn/problem/P3368)

考虑对原数组做差分：

求单点 $\rightarrow$ 求前缀和\
修改区间 $\rightarrow$ 单点修改（两次）

```cpp
#include<bits/stdc++.h>
#define for_i(i,l,r) for(int i=(l);i<=(r);i++)
#define for_j(i,r,l) for(int i=(r);i>=(l);i--)
#define ll long long
#define endl '\n'
using namespace std;
const int N=5e5+10;
int n,m,op,x,y;
int a[N];
ll c[N],k;
ll query(int x)
{
    ll s=0;
    while(x)
    {
        s+=c[x];
        x-=x&(-x);
    }
    return s;
}
void modify(int x,ll s)
{
    while(x<=n)
    {
        c[x]+=s;
        x+=x&(-x);
    }
}
int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
//	freopen(".in","r",stdin);
//	freopen(".out","w",stdout);
    cin>>n>>m;
    for_i(i,1,n)
    {
        cin>>a[i];
        modify(i,a[i]-a[i-1]);
    }
    while(m--)
    {
        cin>>op;
        if(op==1)
        {
            cin>>x>>y>>k;
            modify(x,k);
            modify(y+1,-k);
        }
        else
        {
            cin>>x;
            cout<<query(x)<<endl;
        }
